import json,pathlib
for name in ['source.json','policy.json','coordination.json','reference-targets.json']:
 p=pathlib.Path(name); x=json.loads(p.read_text()); print(name, 'bytes',p.stat().st_size,'type',type(x).__name__)
 if isinstance(x,dict):
  print('keys',[(k,type(v).__name__,len(v) if hasattr(v,'__len__') else None) for k,v in x.items()])
 elif isinstance(x,list):
  print('count',len(x)); print('item keys',list(x[0]))
